✅️ Polynomial.eval (↑(fiber 0)) P * ((1 - r_chal) * ↑(fiber 1) - r_chal) +
  Polynomial.eval (↑(fiber 1)) P *
    (r_chal - (1 - r_chal) * ↑(fiber 0)) =?= have fiberMap := qMap_total_fiber 𝔽q β ⟨↑i, ⋯⟩ 1 h_i_succ_lt y;
have x₀ := fiberMap 0;
have x₁ := fiberMap 1;
have f_x₀ := f x₀;
have f_x₁ := f x₁;
f_x₀ * ((1 - r_chal) * ↑x₁ - r_chal) + f_x₁ * (r_chal - (1 - r_chal) * ↑x₀)

